{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Physical activity containing behavioural interventions for adults living with modi fi able chronic non-communicable diseases in Africa: a systematic mixed-studies review",
      "reason": "The title explicitly identifies the report as a systematic review ('a systematic mixed-studies review')."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Physical activity containing behavioural interventions for adults living with modi fi able chronic non-communicable diseases in Africa",
      "reason": "The title states the intervention (physical activity containing behavioural interventions), the population (adults living with modifiable chronic non-communicable diseases), and the setting (Africa)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "a systematic mixed-studies review",
      "reason": "The title's subtitle provides supplementary information on included study designs ('mixed-studies', i.e., both quantitative/clinical and qualitative studies), which is relevant supplementary detail."
    }
  ],
  "confidence": 95
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Eighty per cent of chronic non-communicable disease (NCD) mortality occurs in developing countries, particularly in Africa... Evidence-based treatment guidelines for NCDs recommend physical activity to improve physiological, cognitive, emotional, social and psychosocial functioning... However, independent of gender, ethnicity and income, more than half of all adults in Africa are inactive.",
      "reason": "The Introduction describes the current state of knowledge (NCD burden, guideline recommendations, evidence that interventions can increase physical activity) and highlights the uncertainty of widespread physical inactivity in Africa."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "No systematic review has examined the effects of behaviour change interventions on physical activity behaviour of people living with chronic NCDs in Africa; patients' experiences of these interventions; and to what extent interventions addressed patients' concerns. These are the objectives of this study.",
      "reason": "The need and importance of the review is explicitly explained by identifying the evidence gap and stating the review objectives."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "No systematic review has examined the effects of behaviour change interventions on physical activity behaviour of people living with chronic NCDs in Africa",
      "reason": "The authors state that no similar systematic review exists for this population/context, so there is no previous review to cite or justify an update against."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Behaviour-change intervention components are the techniques that constitute the active ingredients of the intervention, and the procedures used to deliver those techniques... Behaviour change techniques (BCTs) are replicable components of an intervention designed to alter/redirect causal processes that regulate behaviour",
      "reason": "The Introduction defines BCTs and their role in altering causal processes regulating behaviour, providing a partial conceptual account of the intervention mechanism, but a fuller proposed mechanism of action linking physical activity to health outcomes is only briefly touched on via guideline recommendations."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although the interventions are acknowledged as complex ('They are often complex, comprising many interacting components'), no logic model or diagram of hypothesised relationships between intervention components and outcomes is reported anywhere in the retrieved evidence."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "No systematic review has examined the effects of behaviour change interventions on physical activity behaviour of people living with chronic NCDs in Africa; patients' experiences of these interventions; and to what extent interventions addressed patients' concerns. These are the objectives of this study.",
      "reason": "The review objectives are explicitly stated (effects of interventions, patient experiences, extent interventions addressed concerns), but they are not formulated using a recognised question-formulation framework (e.g., PICO, SPIDER, PICo), so the element is only partially met."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although the review evaluates intervention effects, no planned comparisons are stated using PICO or an appropriate variant. The evidence only notes broad eligibility criteria (e.g., 'There were no restrictions on study design, comparators and timing' in text_2) without a structured statement of population, intervention, comparator and outcomes for the planned comparisons."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "We used a combination of Medical Subject Headings, free text terms and word variants for hypertension, diabetes, obesity and chronic musculoskeletal pain conditions, African search filter, and the search filters for three study types - clinical trials, qualitative and observational studies... These conditions were selected because they are the most prevalent in Africa",
      "reason": "Some eligibility-relevant characteristics are specified: the eligible conditions (hypertension, diabetes, obesity, chronic musculoskeletal pain), study types (clinical trials, qualitative, observational), and African setting (via the African search filter). The PRISMA flow diagram figure (image figure_2, parent chunk text_4) also shows exclusions such as 'Population: African Americans or African ethnic minority groups in non-African countries', 'Intervention: No physical activity component', and 'Outcome evaluation: No physical activity behaviour assessment'. However, a complete statement of eligibility criteria, including population age (adults), setting details, and follow-up requirements, is not explicitly reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "We also searched grey literature as described in the protocol.",
      "reason": "Searching grey literature and databases from their inception dates up to 19 April 2017 suggests that unpublished reports and all publication years were eligible, but the review does not explicitly state eligibility criteria regarding dissemination year, language, or publication status."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_4",
      "quote": "2. b. Outcome evaluation: No physical activity behaviour assessment",
      "reason": "The flow diagram (image figure_2, parent chunk text_4) shows studies excluded because there was no physical activity behaviour assessment (outcomes not measured), but the review does not distinguish exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "Three-stage analyses were carried out using a mixed-studies synthesis design - the sequential explanatory synthesis.",
      "reason": "The groupings for the syntheses are described across the retrieved text: a narrative synthesis of clinical studies (RCTs and B/A studies), a thematic synthesis of qualitative studies ('Qualitative studies were reviewed to explore patients' experiences/perspectives of these interventions'), and a third-stage comparative analysis of clinical and qualitative studies. However, the retrieved evidence does not show how these groups are explicitly linked to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "These conditions were selected because they are the most prevalent in Africa, 1,38 and may be the most easily modified by physical activity. Lung diseases were not included because it was envisaged that a significant proportion may be secondary to communicable diseases, such as tuberculosis.",
      "reason": "The review provides explicit rationales for its notable restrictions: conditions were selected based on prevalence in Africa and modifiability by physical activity, and lung diseases were excluded with a stated reason."
    }
  ],
  "confidence": 78
}

{
