      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "African search filter, 37 word variants for physical activity-related therapies and the search filters for three study types - clinical trials, qualitative and observational studies (supplemental file)",
      "reason": "Published filters (African search filter, study design filters) are cited with a reference, but any adaptations to these filters are not described."
    },
    {
      "element_id": "prisma_2020_7_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No text-analysis or natural-language processing tools used to identify or refine search terms are reported anywhere in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_7_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No tools used to translate search strings between databases are reported; the retrieved evidence only refers to a supplemental file with no mention of translation tools."
    },
    {
      "element_id": "prisma_2020_7_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No validation of the search strategy is described in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_7_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No peer review of the search strategy (e.g., PRESS) is reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_7_e8",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The search combines concept blocks (conditions, geography, physical activity therapies, study types) but the manuscript does not describe the final conceptual structure or its development, nor explicitly state whether PICO was used."
    }
  ],
  "confidence": 80
}

