    },
    {
      "element_id": "prisma_2020_8_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No internally derived machine-learning classifiers are mentioned in the manuscript."
    },
    {
      "element_id": "prisma_2020_8_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
