      "reason": "No machine-learning prioritisation tools or screening stopping rules are reported."
    },
    {
      "element_id": "prisma_2020_8_e10",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No crowdsourcing platforms are mentioned or used in the selection process."
    },
    {
      "element_id": "prisma_2020_8_e11",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No previously screened datasets used to eliminate records are described; the only reuse mentioned is checking a relevant systematic review's reference list, which yielded no additional studies."
    }
  ],
  "confidence": 88
}

