{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "No systematic review has examined the effects of behaviour change interventions on physical activity behaviour of people living with chronic NCDs in Africa; patients' experiences of these interventions; and to what extent interventions addressed patients' concerns. These are the objectives of this study.",
      "reason": "The review's outcome domains can be inferred from the objectives (physical activity behaviour, patients' experiences, and intervention components addressing patients' concerns), and the data collection process is referenced to a published protocol ('The data collection process is detailed in the protocol. 35'). However, there is no explicit 'Data items' section in the Methods that lists and defines all outcome domains for which data were sought."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence specifies the time frame of measurement for each outcome domain. Time points such as '1 year' or '6 months follow-up' appear only in Results/Discussion as characteristics of individual included studies, not as pre-specified time frames for outcome data collection in the Methods."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence contains no statement about whether all compatible results within each outcome domain (all measures, time points, analyses) were sought, nor any criteria for selecting among results."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Since no statement about the completeness of sought results exists, no description of a process for selecting which results to collect is reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence reports any changes to outcome-domain inclusion, definitions, or importance, or rationales for such changes; the evidence only repeatedly refers readers to the published protocol without describing deviations."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence reports changes to the processes used to select results within eligible outcome domains or rationales for such changes."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not explicitly identify which outcomes were considered most important for interpreting conclusions or provide a rationale for prioritising them; comments on physical activity measurement quality appear only in the Discussion and do not constitute a stated prioritisation of outcomes."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "The data collection process is detailed in the protocol. 35 Intervention descriptions were recorded as described by the primary authors and subsequently coded with the taxonomy of hierarchically clustered BCTs 30 using the de fi nition of Michie, Abraham 31 and Whitlock. 33",
      "reason": "The manuscript refers to the protocol for the data collection process rather than explicitly listing and defining all variables sought in the Methods. Variables are only implicitly inferable from results tables (Table 1: country, design, quality, condition, sample size, gender, age, socio-economic status, outcomes, scales, setting; Table 2: similar plus themes; Table 3: BCTs, format, provider/training, duration, frequency, context). The BCT taxonomy used for coding intervention data is cited, but a complete explicit list and definition of all data items is not provided in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_10b_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No statement describing assumptions made about missing or unclear study information is present in the retrieved evidence. Although tables contain 'Not stated' entries, the manuscript does not describe how such missing or unclear information was handled or what assumptions were made."
    },
    {
      "element_id": "prisma_2020_10b_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No tool used to determine which data items to collect (e.g., a data extraction template or guidance tool) is cited anywhere in the retrieved evidence, indicating this reporting requirement does not apply to this manuscript."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_11",
  "elements": [
    {
      "element_id": "prisma_2020_11_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "We assessed the quality of all studies with the Mixed Methods Appraisal Tool (MMAT) 39 as described in the review protocol.",
      "reason": "The risk-of-bias/quality assessment tool (MMAT) is explicitly named."
    },
    {
      "element_id": "prisma_2020_11_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "For RCTs, quality criteria included appropriate random sequence generation/clear description of randomization, allocation concealment or blinding, complete outcome data ( >= 80%) and low drop-out rate ( < 20%). For non-controlled B/A studies, the criteria were low selection bias... For qualitative studies, the criteria were adequate/relevant sources of qualitative data...",
      "reason": "The specific criteria/components of the MMAT applied to each study design are detailed."
    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "For mixed-methods B/A studies, the overall quality score is the lowest score of the study components. ... A total score for each study was based on the number of criteria met (Tables 1 and 3).",
      "reason": "Overall quality scores were derived and the rule for mixed-methods studies stated, but derivation rules for other designs are not fully specified."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4",
      "quote": "We assessed the quality of all studies with the Mixed Methods Appraisal Tool (MMAT) 39 as described in the review protocol.",
      "reason": "No adaptation of an existing tool is reported; the standard MMAT was used as described in the protocol."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4",
      "quote": "We assessed the quality of all studies with the Mixed Methods Appraisal Tool (MMAT) 39",
      "reason": "No newly developed risk-of-bias tool was used; only the existing MMAT was applied."
    },
    {
      "element_id": "prisma_2020_11_e6",
      "status": "PARTIAL",
      "chunk_id": "text_18",
      "quote": "CNI-C, ELG, APK and IOS contributed to further development of the review protocol, selection criteria, quality assessment, the risk of bias assessment, data extraction and analyses.",
      "reason": "Multiple authors conducted quality/risk-of-bias assessment, but independence of assessment and disagreement-resolution procedures specifically for risk-of-bias assessment are not reported (the cross-checking described in text_3 relates to data collection/selection)."
    },
    {
      "element_id": "prisma_2020_11_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of processes to obtain or confirm risk-of-bias information from study investigators."
    },
    {
      "element_id": "prisma_2020_11_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No automation tools were used for risk-of-bias assessment; the assessment was done manually with the MMAT."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "For comparability of results from RCTs and B/A studies, withingroup preand post-physical activity-change score-effect sizes were calculated for each clinical study.",
      "reason": "The manuscript specifies an effect measure (within-group pre/post change score effect sizes) for clinical studies, but this is not specified for every outcome or outcome type (e.g., qualitative synthesis outcomes or secondary outcomes individually), and no effect measure is defined for presentation of other results."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No thresholds or ranges for interpreting effect sizes (e.g., small/medium/large) or their rationale are reported anywhere in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No methods for re-expressing synthesized results using another effect measure are described; meta-analysis was precluded and no conversion of effect measures is reported."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The choice of effect measure is not justified; the text only states change score effect sizes were calculated 'for comparability of results', without a rationale for selecting this measure."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_13a",
  "elements": [
    {
      "element_id": "prisma_2020_13a_e1",
      "status": "PARTIAL",
